class JsonRpcClient(object):
    """
    TCP client to communicate with JSON-RPC server

    the single point to convert Python structures (dict, list, ...) of called remote functions into JSON strings
    singleton
    knows where is server
    handles "JSON-RPC" level-2 envelope (modulecall, classcall, objectcall)
    constructor opens connection to server or fires exception
    """
    def __init__(self, rpc_connection_name, transport_medium, protocol_ver="2.0", log_traffic=True):
        """Jsonrpcclient Init"""
        object.__init__(self)

        self.connection_name = rpc_connection_name
        self.transport_medium = transport_medium
        self.proto_ver = protocol_ver  # 1.0 has no named param fields

        # logsystem.register_connection(connection_name=self.connection_name)
        # self.logger = logging.getLogger("ruff.connection.%s" % self.connection_name) if log_traffic else None

        self._req_id = 0
        self.timeouted_req_ids = {}
        self.braces_stack = []
        self._activated_transport_encoding = None
        # try:
        #     # FUTURE: maybe we change to non-blocking transport
        #     #         but for now any call to RPC is blocking send-receive

        #     # self.transport_medium.open()
        #     # print("Connected to JSON-RPC server")

        #     # inform server about callbacks handler
        #     # data = {"method": "register_callback_handler", "params": {"callback_name": "server_async_calls"}, "id": 1}
        #     # expecting response like:
        #     # {"jsonrpc": "2.0","result": 1,"id": 1}
        #     # registration_status = self._rpc_call(data)
        #     # if 1 != registration_status:
        #     # TODO: log that failed, raise blocking error
        #     #    pass
        #     # else:
        #     #    netstring_activation_req = {"method": "activate_transport_encoding", "params": {"encoding_type": "netstring"}}
        #     # expecting response like:
        #     # {"jsonrpc": "2.0","result": {"activated_transport_encoding": "netstring"},"id": 2}
        #     #    try:
        #     #        result = self._rpc_call(netstring_activation_req)
        #     #        if result == {"activated_transport_encoding": "netstring"}:
        #     #            self._activated_transport_encoding = "netstring"
        #     #    except ErrJsonRpcError as err:
        #     #        self._activated_transport_encoding = None

        # except Exception:  # TODO: handle transport related exceptions only
        #     raise

    def open_connection(self):
        """Method for connection openning"""
        try:
            self.transport_medium.open()
            print("Connected to JSON-RPC server")   # noqa: T201
        except Exception:
            raise

    def __del__(self):
        print("closing JSON-RPC server")   # noqa: T201
        self.transport_medium.close()

    def modulecall(self, module_name, method_name, params=None, expect=None):
        """
        Handle JSON-RPC level-2 envelope

        from like::

            {"module": "json_launcher", "method": "execute_tc", "params": {"-TC": "LIDD_DEFAULTS"}}

        to like::

            {"method": "module_call", "params": {"module": "json_launcher", "method": "execute_tc", "params": {"-TC": "LIDD_DEFAULTS"}}, "id": 1}
        """
        # TODO: provide id and keep it tracked
        data = {"method": "module_call",
                "params": {"module": module_name, "method": method_name, "params": params, "expect": expect},
                "id": None}
        return self._rpc_call(data)

    def call(self, method_name, params=None):
        """RPC call method"""
        data = {"method": method_name,
                "params": params,
                "id": None}
        return self._rpc_call(data)

    def classcall(self, class_name, method_name, params=None, expect=None):
        """
        Handle JSON-RPC level-2 envelope

        from like::

        {"class": "DevMgr", "method": "get_device", "params": {"-NAME":"JSON-RPC-SERVER"}, "expect"="object_instance"}

        to like::

        {"method":"class_call","params":{"class":"DevMgr","method":"get_device","params":{"-NAME":"JSON-RPC-SERVER"},"expect"="object_instance"},"id":1}
        """
        data = {"method": "class_call",
                "params": {"class": class_name, "method": method_name, "params": params, "expect": expect}, "id": None}
        return self._rpc_call(data)

    def objectcall(self, object_instance, method_name, params=None, expect=None):
        """
        Handle JSON-RPC level-2 envelope

        from like::

        {"object_id": "Command::BCU::iscli::show_running_config=HASH(0x5d076c8)", "method": "run", expect": "scalar"}

        to like::

        {"method":"object_call","params":{"object_id":"Command::BCU::iscli::show_running_config=HASH(0x5d076c8)","method":"run",expect":"scalar"},"id":1}
        """
        data = {"method": "object_call",
                "params": {"object_id": object_instance, "method": method_name, "params": params, "expect": expect},
                "id": None}
        return self._rpc_call(data)

    def _next_msg_id(self):
        self._req_id = (self._req_id + 1) % 60000
        return self._req_id

    def _set_timeout(self, data):
        """Simple method for timeout"""
        if data['method']['module'].startswith('Elixir'):
            timeout = data['method'].pop('response_timeout', None)
        else:
            timeout = data["params"]["params"]["-TIMEOUT"]
        if timeout is None:
            timeout = 60
        return timeout

    def _timeout_handling(self, resp_id):
        """Timeout and resp ID handling"""
        if resp_id in self.timeouted_req_ids:
            # so, it is delayed response - just throw it away
            # print "catched delayed response for timeouted request(id:%s) %s" % (resp_id, rpc_formated_response[:40] + rpc_formated_response[-10:])
            # received_response = False
            del self.timeouted_req_ids[resp_id]
        else:
            raise ErrJsonRpcWrongRespId  # noqa: F405

    def _receive_response(self, start_time, timeout, data):
        """Getting response output"""
        received_response = False
        while (not received_response):
            try:
                rpc_formated_response = self._recv(timeout=timeout, start_time=start_time)
                # print "rpc call - jsonrpc: " + rpc_formated_response
                rpc_resp_data = self.decode(rpc_formated_response)
                self.validate_rpc_response(req_data=data, resp_data=rpc_resp_data)
                received_response = True
                return rpc_resp_data
            except ErrTransportTimeout:
                # remember timeouted requests
                self.timeouted_req_ids[data["id"]] = 1
                # print "timeout awaiting response for %s" % rpc_formated_request
                raise
            except ErrJsonRpcWrongRespId as exc:  # noqa: F405
                resp_id = exc.err["resp"]["id"]
                # check if it is delayed response for timeouted request
                self._timeout_handling(resp_id)

    def _rpc_call(self, data):
        """
        Convert python data to transfer form of used RPC protocol
        send it to JSON-RPC server
        await RPC response
        convert response back to python data types
        raise exception if response carries error or,
        return value of RPC called remote function
        """
        data["id"] = self._next_msg_id()
        if self.proto_ver == "2.0":
            data["jsonrpc"] = "2.0"
        try:
            timeout = self._set_timeout(data)
        except Exception:
            timeout = 600

        # TODO: for ver 1.0 convert data["params"] from dict to list - do we need it?
        rpc_formated_request = self.encode(data)
        self._send(rpc_formated_request)
        start_time = float(time.time())
        # received_response = False

        rpc_resp_data = self._receive_response(start_time, timeout, data)

        returned_value = self._handle_response(req_data=data, resp_data=rpc_resp_data)
        # print "returned value:" +  returned_value  # debug print
        return returned_value

    def _send(self, rpc_formated_request):
        request_to_send = rpc_formated_request
        if self._activated_transport_encoding == "netstring":
            request_to_send = "%i:%s," % (len(rpc_formated_request), rpc_formated_request)
        self.transport_medium.send(request_to_send)

    def _recv(self, timeout, start_time):
        """Await JSON response - complete JSON from chunks if needed"""
        if self._activated_transport_encoding == "netstring":
            rpc_formated_response = self._recv_based_on_netstring_frame(timeout=timeout, start_time=start_time)
            # print "_recv: "  + rpc_formated_response
        else:
            # rpc_formated_response = self._recv_based_on_json_braces_completion(timeout=timeout, start_time=start_time)
            rpc_formated_response = self._recv_based_on_json_parsing_trials(timeout=timeout, start_time=start_time)
        return rpc_formated_response

    def _check_timeout(self, started, whole_timeout, timeout):
        """Countdown and update the timeout"""
        now = time.time()
        if now - started >= whole_timeout:
            raise ErrTransportTimeout(
                "Timeout (> %.3f sec) inside jsonrpc._recv_based_on_netstring_frame %s >= %s" % (
                    whole_timeout, now - started, timeout))
        else:
            timeout = whole_timeout - (now - started)
        return timeout

    def _netstring_decoder(self, data_size, json_chunk):
        """Netstring deocder"""
        if data_size is None:
            (size_str, _, json_data) = json_chunk.partition(b':')
            if ((not _) and (not json_data)) or (not size_str.isdigit()):
                raise ErrJsonRpcMissingNetstringFrame(  # noqa: F405
                    "Can't find start of netstring (<data_size>: ) inside:\n%s" % json_chunk)
            if size_str[0] == '0':
                raise ErrJsonRpcMissingNetstringFrame(  # noqa: F405
                    "Netstring size may not start from 0 digit:\n%s" % json_chunk)
            data_size = int(size_str)
            json_chunk = json_data
        return (data_size, json_chunk)

    def _recv_based_on_netstring_frame(self, timeout, start_time):
        """
        Await JSON response - complete JSON from chunks if needed
        JSON completeness detection based on encapsulation inside netstring frame
        (netstring carries bytesize of enclosed JSON)
        """
        whole_json = b''
        data_size = None  # means unknown
        started = start_time
        whole_timeout = float(timeout)
        while True:
            timeout = self._check_timeout(started, whole_timeout, timeout)
            try:
                json_chunk = self.transport_medium.receive(
                    timeout=timeout + 0.5)  # handling huge responses - fragmented JSON: looped read till completed or timeout

                (data_size, json_chunk) = self._netstring_decoder(data_size, json_chunk)
                whole_json = whole_json + json_chunk  # concatenate with previous read

                data_size_already_received = len(whole_json)
                if data_size_already_received == data_size + 1:
                    # ----------------------------------------------------------------------------
                    whole_json = whole_json[:data_size]  # !!!!!!! extract JSON payload !!!!!!!!!
                    # ----------------------------------------------------------------------------
                    break
                # else:  await for remaining bytes and concatenate them to  whole_json  buffer

            except Exception:  # TODO: handle socket related exceptions only
                raise
        # print "exit fun netstring unpack"
        return whole_json

    def _is_complete_json(self, json_str):
        if len(self.braces_stack):
            top = self.braces_stack.pop()
            json_str = top + json_str
        if json_str is None:
            return None
        braces = re.findall(r"[{}\[\]][^{}\[\]]*", json_str)

        if 0 == len(self.braces_stack):
            self.braces_stack = [braces.pop(0)]

        for brace in braces:
            self._add_brace_to_braces_stack(brace)
        return None

    def _add_brace_to_braces_stack(self, brace):
        if (brace[0] == '}' and self.braces_stack[-1][0] == '{') or (
                brace[0] == ']' and self.braces_stack[-1][0] == '['):
            top = self.braces_stack.pop()
            completed_part = top + brace
            if 0 == len(self.braces_stack):
                return completed_part
            else:
                top = self.braces_stack.pop()
                self.braces_stack.append(top + completed_part)
        else:
            self.braces_stack.append(brace)

    def _handle_response(self, req_data, resp_data):
        """Handle JSON-RPC server response - return data or fire exceptions"""
        # raise exception on error responses from called functions
        if "error" in resp_data:
            # err_data = req_data["params"]
            err_data = resp_data["error"]
            if req_data["method"] == "module_call":
                raise ErrJsonRpcModuleMethod(err_data)  # noqa: F405
            elif req_data["method"] == "class_call":
                raise ErrJsonRpcClassMethod(err_data)  # noqa: F405
            elif req_data["method"] == "instance_call":
                raise ErrJsonRpcInstanceMethod(err_data)  # noqa: F405
            else:
                raise ErrJsonRpcError(err_data)  # noqa: F405

        # return data from correct responses
        if "result" in resp_data:
            return resp_data["result"]
        else:
            return None

    # all methods below are strictly related to JSON-RPC protocol v. 1.0 and 2.0

    def validate_rpc_response(self, req_data, resp_data):
        """
        Validate response of given RPC protocol (here JSON-RPC)
        fire exceptions on:
        - incorrect response
        - response with error notification
        """
        # validate JSON-RPC correctness
        if req_data["id"] != resp_data["id"]:
            self.transport_medium.logger.debug('ErrJsonRpcWrongRespId: req_data: {}; resp_data: {}'.format(req_data, resp_data))
            raise ErrJsonRpcWrongRespId({"req": req_data, "resp": resp_data})  # noqa: F405
        # ver = "1.0"
        # if ("jsonrpc" in resp_data) and (resp_data["jsonrpc"] == "2.0"):
        #     ver = "2.0"
        # normalize to v 2.0 error - if no error is expressed by lack of "error" key
        if ("error" in resp_data) and (resp_data["error"] is None):
            del resp_data["error"]
        # TODO: check if we have all fields required by JSON-RPC v. 1.0 or 2.0
        if ("error" in resp_data) and ("code" in resp_data["error"]):
            print("resp_data ", json.dumps(resp_data))  # noqa: T201
            err_code = resp_data["error"]["code"]
            if (err_code >= -32768) and (err_code <= -32000):
                raise ErrJsonRpcError({"req": req_data, "resp": resp_data})  # noqa: F405

    def decode(self, rpc_formated_data):
        """Decode from used RPC protocol form (here JSON string) to Python structures (dict, list, ...)"""
        try:
            data = json.loads(
                rpc_formated_data)  # TODO: support loop fragmented JSON - fire ErrJsonRpcFragment
            return data
        except Exception:  # TODO: handle library related exceptions only
            raise

    def encode(self, data):
        """Encode Python structures (dict, list, ...) into used RPC protocol form (here JSON string)"""
        try:
            json_str = json.dumps(data, sort_keys=True, separators=(',', ': '))
            rpc_formated_data = json_str
            return rpc_formated_data
        except Exception:  # TODO: handle library related exceptions only
            raise


